  'inicio.pilar3':              { es: 'Los Saberes', en: 'The Knowledge', fr: 'Les Savoirs', it: 'I Saperi', pt: 'Os Saberes' },
  'inicio.pilar3Desc':          { es: 'El significado detrás de los símbolos.', en: 'The meaning behind the symbols.', fr: 'Le sens derrière les symboles.', it: 'Il significato dietro i simboli.', pt: 'O significado por trás dos símbolos.' },
  'inicio.pilar4':              { es: 'La Transformación', en: 'The Transformation', fr: 'La Transformation', it: 'La Trasformazione', pt: 'A Transformação' },
