  'inicio.leerHistoria':        { es: 'Leer la historia completa', en: 'Read the full story', fr: "Lire l'histoire complète", it: 'Leggi la storia completa', pt: 'Ler a história completa' },
  'inicio.desde1994':           { es: 'Desde 1994', en: 'Since 1994', fr: 'Depuis 1994', it: 'Dal 1994', pt: 'Desde 1994' },
  'inicio.cita':                { es: '«La mola no es un adorno: es memoria cosida a mano»', en: '"The mola is not an ornament: it is memory sewn by hand"', fr: "« La mola n'est pas un ornement : c'est la mémoire cousue à la main »", it: '«La mola non è un ornamento: è memoria cucita a mano»', pt: '«A mola não é um adorno: é memória costurada à mão»' },
  'inicio.citaAutor':           { es: 'Liseth Martínez Cuesta · Fundadora', en: 'Liseth Martínez Cuesta · Founder', fr: 'Liseth Martínez Cuesta · Fondatrice', it: 'Liseth Martínez Cuesta · Fondatrice', pt: 'Liseth Martínez Cuesta · Fundadora' },
    'pie.tagline': { es: 'Moda con propósito desde el Pacífico colombiano.', en: 'Fashion with purpose from the Colombian Pacific.', fr: 'Une mode avec un propos, née du Pacifique colombien.', it: 'Moda con uno scopo dal Pacifico colombiano.', pt: 'Moda com propósito desde o Pacífico colombiano.' },
      'horario.eyebrow': { es: '03 — Visítanos', en: '03 — Visit us', fr: '03 — Nous rendre visite', it: '03 — Vieni a trovarci', pt: '03 — Visite-nos' },
